/**
 * Project-level configuration for kspec.
 *
 * Loads kspec.config.yaml from the project root (main branch) before shadow
 * branch detection. All fields are optional with backward-compatible defaults.
 *
 * Priority: env vars > config file > defaults
 *
 * @module
 */

import * as fs from "node:fs/promises";
import * as path from "node:path";
import { z } from "zod";
import * as YAML from "yaml";
import { getGitRoot } from "./shadow.js";

// ── Schema ──────────────────────────────────────────────────────────────

/**
 * Schema for shadow branch configuration.
 *
 * AC: @config-shadow — shadow.branch, shadow.directory, shadow.remote configurable
 */
const ShadowConfigSchema = z
  .object({
    /** Branch name for shadow branch (default: kspec-meta) */
    branch: z.string().optional(),
    /** Worktree directory name (default: .kspec) */
    directory: z.string().optional(),
    /**
     * Remote target for shadow branch. Can be:
     * - Named remote (e.g., "origin", "specs-origin")
     * - Local filesystem path (starts with /, ./, or ~)
     * - Git URL (contains :// or starts with git@)
     */
    remote: z.string().optional(),
    /**
     * Interval in seconds for periodic background shadow pull in daemon mode.
     * Set to 0 to disable periodic sync. Default: 60.
     *
     * AC: @config-shadow ac-12 — configurable sync interval for daemon background pull
     */
    sync_interval: z.number().int().min(0).optional(),
  })
  .strict()
  .optional();

/**
 * Schema for identity configuration.
 */
const IdentityConfigSchema = z
  .object({
    /** Default author for notes/tasks (overridden by KSPEC_AUTHOR env var) */
    author: z.string().optional(),
  })
  .strict()
  .optional();

/**
 * Schema for validation configuration.
 *
 * AC: @config-validation — validation settings configurable in kspec.config.yaml
 */
const ValidationConfigSchema = z
  .object({
    /**
     * When true, dangling references are treated as errors instead of warnings.
     * AC: @config-validation ac-2 ac-3 — strict_refs configurable
     */
    strict_refs: z.boolean().optional(),
    /**
     * When true, specs missing acceptance criteria are reported as errors not warnings.
     * AC: @config-validation ac-1 — require_acceptance configurable
     */
    require_acceptance: z.boolean().optional(),
  })
  .strict()
  .optional();

/**
 * Schema for daemon configuration.
 *
 * AC: @config-daemon — daemon.port, daemon.auto_start configurable
 */
const DaemonConfigSchema = z
  .object({
    /** Default port for daemon (default: 3456) */
    port: z.number().int().min(1).max(65535).optional(),
    /** Host to bind to (default: localhost) */
    host: z.string().optional(),
    /**
     * Whether to auto-start daemon when running kspec commands.
     * AC: @config-daemon ac-3 — auto_start configurable
     */
    auto_start: z.boolean().optional(),
  })
  .strict()
  .optional();

/**
 * Schema for ralph skill name overrides.
 *
 * Ralph prompts reference skills by invocation name. These default to
 * kspec: namespace core skills but can be overridden per-project for
 * projects that use project-specific skill names.
 */
const RalphSkillsSchema = z
  .object({
    /** Skill invocation for task-work (default: /kspec:task-work) */
    task_work: z.string().optional(),
    /** Skill invocation for reflect (default: /kspec:reflect) */
    reflect: z.string().optional(),
    /** Skill invocation for PR review (default: /kspec:review) */
    pr_review: z.string().optional(),
  })
  .strict()
  .optional();

/**
 * Schema for ralph configuration.
 */
const RalphConfigSchema = z
  .object({
    /** Skill invocation name overrides */
    skills: RalphSkillsSchema,
  })
  .strict()
  .optional();

/**
 * Complete schema for kspec.config.yaml.
 *
 * AC: @project-config ac-4 — unknown fields are ignored via passthrough
 */
export const KspecConfigSchema = z
  .object({
    /** Shadow branch configuration */
    shadow: ShadowConfigSchema,
    /** Identity configuration */
    identity: IdentityConfigSchema,
    /** Validation configuration */
    validation: ValidationConfigSchema,
    /** Daemon configuration */
    daemon: DaemonConfigSchema,
    /** Ralph automation configuration */
    ralph: RalphConfigSchema,
  })
  .passthrough(); // AC: ac-4 — ignore unknown fields

/**
 * Raw config type as parsed from YAML file.
 */
export type KspecConfig = z.infer<typeof KspecConfigSchema>;

/**
 * Remote type for shadow branch configuration.
 * - "named": Git remote name (e.g., "origin", "specs-origin")
 * - "path": Local filesystem path
 * - "url": Git URL (https://, git@, etc.)
 */
export type ShadowRemoteType = "named" | "path" | "url";

/**
 * Resolved shadow remote configuration.
 */
export interface ResolvedShadowRemote {
  /** The remote value from config */
  value: string;
  /** Detected type of the remote */
  type: ShadowRemoteType;
}

/**
 * Detect the type of a shadow remote string.
 *
 * AC: @config-shadow ac-3 ac-4 ac-5 — remote type detection
 *
 * @param remote Remote string from config
 * @returns Detected type: "path" for filesystem, "url" for git URLs, "named" for git remote names
 */
export function detectRemoteType(remote: string): ShadowRemoteType {
  // AC: ac-4 — Local filesystem path (starts with /, ./, ../, or ~)
  if (
    remote.startsWith("/") ||
    remote.startsWith("./") ||
    remote.startsWith("../") ||
    remote.startsWith("~")
  ) {
    return "path";
  }
  // AC: ac-5 — Git URL (contains :// or starts with git@)
  if (remote.includes("://") || remote.startsWith("git@")) {
    return "url";
  }
  // AC: ac-3 — Otherwise it's a named remote
  return "named";
}

/**
 * Resolved config with all values finalized (env vars applied, defaults filled).
 */
export interface ResolvedKspecConfig {
  shadow: {
    /** Branch name (default: kspec-meta) */
    branch: string;
    /** Worktree directory name (default: .kspec) */
    directory: string;
    /** Remote configuration, null if not specified */
    remote: ResolvedShadowRemote | null;
    /**
     * Interval in seconds for periodic background shadow pull in daemon mode.
     * 0 disables periodic sync. Default: 60.
     * AC: @config-shadow ac-12
     */
    sync_interval: number;
  };
  identity: {
    author: string | null;
  };
  validation: {
    /**
     * When true, dangling references are treated as errors instead of warnings.
     * AC: @config-validation ac-2 ac-3
     */
    strict_refs: boolean;
    /**
     * When true, specs missing acceptance criteria are reported as errors not warnings.
     * AC: @config-validation ac-1
     */
    require_acceptance: boolean;
  };
  daemon: {
    port: number;
    host: string;
    /**
     * Whether to auto-start daemon when running kspec commands.
     * AC: @config-daemon ac-3
     */
    auto_start: boolean;
  };
  ralph: {
    skills: {
      /** Skill invocation for task-work (default: /kspec:task-work) */
      task_work: string;
      /** Skill invocation for reflect (default: /kspec:reflect) */
      reflect: string;
      /** Skill invocation for PR review (default: /kspec:review) */
      pr_review: string;
    };
  };
}

// ── Defaults ────────────────────────────────────────────────────────────

/**
 * Default configuration values.
 *
 * AC: @project-config ac-1 — these are the current defaults
 */
const DEFAULT_CONFIG: ResolvedKspecConfig = {
  shadow: {
    branch: "kspec-meta",
    directory: ".kspec",
    remote: null,
    sync_interval: 60, // AC: @config-shadow ac-12 — default 60s
  },
  identity: {
    author: null,
  },
  validation: {
    // AC: @config-validation — defaults preserve existing behavior
    // strict_refs: true = dangling refs are errors (existing behavior)
    // require_acceptance: false = missing AC is warning (existing behavior)
    strict_refs: true,
    require_acceptance: false,
  },
  daemon: {
    port: 3456,
    host: "localhost",
    auto_start: true, // AC: @config-daemon — default auto-start enabled
  },
  ralph: {
    skills: {
      task_work: "/kspec:task-work",
      reflect: "/kspec:reflect",
      pr_review: "/kspec:review",
    },
  },
};

// ── Loading ─────────────────────────────────────────────────────────────

const CONFIG_FILENAME = "kspec.config.yaml";

/**
 * Result of loading project config.
 */
export interface LoadConfigResult {
  /** Resolved configuration with all values finalized */
  config: ResolvedKspecConfig;
  /** Path to config file if found, null otherwise */
  configPath: string | null;
  /** Warning message if config had issues but was recoverable */
  warning: string | null;
  /** The git root directory where config was loaded from */
  gitRoot: string | null;
}

/**
 * Find git root directory, handling KSPEC_SPEC_DIR batch mode.
 *
 * AC: @project-config ac-7 — in batch mode, we need the REAL project root
 *
 * When KSPEC_SPEC_DIR is set (batch atomic mode), the cwd might be the temp
 * directory. We need to find the real project root by checking:
 * 1. If KSPEC_BATCH_PROJECT_ROOT is set, use that (set by batch executor)
 * 2. Otherwise, use git root from cwd
 *
 * AC: @project-config ac-6 — loads from git root, not cwd subdirectory
 */
export function findProjectRoot(startDir: string): string | null {
  // In batch mode, the batch executor should set this to the real root
  // before redirecting KSPEC_SPEC_DIR
  const batchRoot = process.env.KSPEC_BATCH_PROJECT_ROOT;
  if (batchRoot) {
    return batchRoot;
  }

  // Normal mode: find git root
  return getGitRoot(startDir);
}

/**
 * Load project configuration from kspec.config.yaml.
 *
 * AC: @project-config ac-1 — no config = all defaults
 * AC: @project-config ac-2 — config parsed and available before shadow detection
 * AC: @project-config ac-3 — invalid YAML = defaults + warning
 * AC: @project-config ac-4 — unknown fields ignored
 * AC: @project-config ac-5 — env vars take precedence
 * AC: @project-config ac-6 — loads from git root
 * AC: @project-config ac-7 — batch mode uses real project root
 *
 * @param startDir Starting directory for git root detection
 */
export async function loadProjectConfig(
  startDir: string = process.cwd(),
): Promise<LoadConfigResult> {
  const gitRoot = findProjectRoot(startDir);

  if (!gitRoot) {
    // Not in a git repo, use defaults
    return {
      config: resolveConfig(null),
      configPath: null,
      warning: null,
      gitRoot: null,
    };
  }

  const configPath = path.join(gitRoot, CONFIG_FILENAME);

  // Check if config file exists
  try {
    await fs.access(configPath);
  } catch {
    // AC: ac-1 — no config file, use defaults
    return {
      config: resolveConfig(null),
      configPath: null,
      warning: null,
      gitRoot,
    };
  }

  // Try to load and parse config
  try {
    const content = await fs.readFile(configPath, "utf-8");
    const raw = YAML.parse(content);

    // Validate against schema
    const result = KspecConfigSchema.safeParse(raw);

    if (!result.success) {
      // AC: ac-3 — validation error = defaults + warning
      const issues = result.error.issues
        .map((i) => `${i.path.join(".")}: ${i.message}`)
        .join("; ");
      return {
        config: resolveConfig(null),
        configPath,
        warning: `Config validation failed: ${issues}. Using defaults.`,
        gitRoot,
      };
    }

    // AC: ac-5 — apply env var overrides during resolution
    return {
      config: resolveConfig(result.data),
      configPath,
      warning: null,
      gitRoot,
    };
  } catch (err) {
    // AC: ac-3 — parse error = defaults + warning
    const message = err instanceof Error ? err.message : String(err);
    return {
      config: resolveConfig(null),
      configPath,
      warning: `Failed to parse ${CONFIG_FILENAME}: ${message}. Using defaults.`,
      gitRoot,
    };
  }
}

/**
 * Resolve configuration by merging file config with env vars and defaults.
 *
 * Priority: env vars > config file > defaults
 *
 * AC: @project-config ac-5 — env vars take precedence
 */
export function resolveConfig(fileConfig: KspecConfig | null): ResolvedKspecConfig {
  const file = fileConfig || {};

  // Get env var overrides
  const envAuthor = process.env.KSPEC_AUTHOR;
  const envPort = process.env.KSPEC_DAEMON_PORT
    ? parseInt(process.env.KSPEC_DAEMON_PORT, 10)
    : undefined;
  const envHost = process.env.KSPEC_DAEMON_HOST;

  // Resolve shadow remote if specified
  const remoteValue = file.shadow?.remote;
  const resolvedRemote: ResolvedShadowRemote | null = remoteValue
    ? { value: remoteValue, type: detectRemoteType(remoteValue) }
    : DEFAULT_CONFIG.shadow.remote;

  return {
    shadow: {
      branch: file.shadow?.branch ?? DEFAULT_CONFIG.shadow.branch,
      directory: file.shadow?.directory ?? DEFAULT_CONFIG.shadow.directory,
      remote: resolvedRemote,
      sync_interval: file.shadow?.sync_interval ?? DEFAULT_CONFIG.shadow.sync_interval,
    },
    identity: {
      // AC: ac-5 — env var takes precedence
      author: envAuthor ?? file.identity?.author ?? DEFAULT_CONFIG.identity.author,
    },
    validation: {
      // AC: @config-validation ac-2 ac-3 — strict_refs from config
      strict_refs:
        file.validation?.strict_refs ?? DEFAULT_CONFIG.validation.strict_refs,
      // AC: @config-validation ac-1 — require_acceptance from config
      require_acceptance:
        file.validation?.require_acceptance ?? DEFAULT_CONFIG.validation.require_acceptance,
    },
    daemon: {
      // AC: ac-5 — env vars take precedence
      port:
        (envPort && !isNaN(envPort) ? envPort : undefined) ??
        file.daemon?.port ??
        DEFAULT_CONFIG.daemon.port,
      // AC: @config-daemon ac-5 ac-6 — host from config/env
      host: envHost ?? file.daemon?.host ?? DEFAULT_CONFIG.daemon.host,
      // AC: @config-daemon ac-3 — auto_start from config
      auto_start: file.daemon?.auto_start ?? DEFAULT_CONFIG.daemon.auto_start,
    },
    ralph: {
      skills: {
        task_work: file.ralph?.skills?.task_work ?? DEFAULT_CONFIG.ralph.skills.task_work,
        reflect: file.ralph?.skills?.reflect ?? DEFAULT_CONFIG.ralph.skills.reflect,
        pr_review: file.ralph?.skills?.pr_review ?? DEFAULT_CONFIG.ralph.skills.pr_review,
      },
    },
  };
}

/**
 * Get the default configuration (no file, no env vars).
 * Useful for testing or when config loading fails completely.
 * Returns a deep copy to prevent mutation of shared defaults.
 */
export function getDefaultConfig(): ResolvedKspecConfig {
  return {
    shadow: {
      branch: DEFAULT_CONFIG.shadow.branch,
      directory: DEFAULT_CONFIG.shadow.directory,
      remote: DEFAULT_CONFIG.shadow.remote,
      sync_interval: DEFAULT_CONFIG.shadow.sync_interval,
    },
    identity: { ...DEFAULT_CONFIG.identity },
    validation: {
      strict_refs: DEFAULT_CONFIG.validation.strict_refs,
      require_acceptance: DEFAULT_CONFIG.validation.require_acceptance,
    },
    daemon: {
      port: DEFAULT_CONFIG.daemon.port,
      host: DEFAULT_CONFIG.daemon.host,
      auto_start: DEFAULT_CONFIG.daemon.auto_start,
    },
    ralph: {
      skills: { ...DEFAULT_CONFIG.ralph.skills },
    },
  };
}

/**
 * Kspec Daemon Server
 *
 * Elysia.js HTTP server with WebSocket support for real-time kspec state updates.
 * Implements localhost-only security, file watching, and graceful shutdown.
 */

import { Elysia } from 'elysia';
import { cors } from '@elysiajs/cors';
import { staticPlugin } from '@elysiajs/static';
import { ulid } from 'ulidx';
import { existsSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname } from 'path';
import { PubSubManager } from './websocket/pubsub';
import { HeartbeatManager } from './websocket/heartbeat';
import { WebSocketHandler } from './websocket/handler';
import { handleWebSocketClose } from './websocket/lifecycle';
import type { ConnectionData, ConnectedEvent } from './websocket/types';
import { PidFileManager } from './pid';
import { projectContextMiddleware } from './middleware/project-context';
import { createTasksRoutes } from './routes/tasks';
import { createItemsRoutes } from './routes/items';
import { createInboxRoutes } from './routes/inbox';
import { createMetaRoutes } from './routes/meta';
import { createValidationRoutes } from './routes/validation';
import { createProjectsRoutes } from './routes/projects';
import { createTriageRoutes } from './routes/triage';
import { createAgentDispatchRoutes, getDispatchEngine, stopAllEngines } from './routes/agent-dispatch';
import { createSessionRoutes } from './routes/sessions';
import { createPlansRoutes } from './routes/plans';
import { ShadowSyncScheduler } from './shadow-sync';
import { SessionSyncScheduler } from './session-sync';
import { join } from 'path';

export interface ServerOptions {
  port: number;
  isDaemon: boolean;
  kspecDir?: string; // Path to .kspec directory (default: .kspec in cwd)
  webUiDir?: string; // Path to web UI build directory (default: auto-detect)
}

/**
 * Resolves the path to the web UI build directory.
 * Tries multiple locations in order:
 * 1. Explicit webUiDir option
 * 2. WEB_UI_DIR environment variable
 * 3. packages/web-ui/build in current working directory (monorepo dev)
 * 4. web-ui/build in current working directory
 * 5. Bundled dist/web-ui/ relative to this module (npm package installs)
 *
 * Exported for testing only.
 */
export function resolveWebUiPath(webUiDir?: string): string | null {
  // 1. Explicit option
  if (webUiDir && existsSync(webUiDir)) {
    return webUiDir;
  }

  // 2. Environment variable
  const envPath = process.env.WEB_UI_DIR;
  if (envPath && existsSync(envPath)) {
    return envPath;
  }

  // 3. Monorepo development: packages/web-ui/build from cwd
  // The daemon is spawned with cwd set to project root
  const monorepoPath = join(process.cwd(), 'packages', 'web-ui', 'build');
  if (existsSync(monorepoPath)) {
    return monorepoPath;
  }

  // 4. Alternate location: web-ui/build in cwd
  const altPath = join(process.cwd(), 'web-ui', 'build');
  if (existsSync(altPath)) {
    return altPath;
  }

  // 5. Bundled assets: dist/web-ui/ relative to daemon module location
  // Covers npm package installs where no local web UI build exists.
  // import.meta.url resolves to dist/daemon/server.js → sibling is dist/web-ui/
  const selfDir = dirname(fileURLToPath(import.meta.url));
  const bundledPath = join(selfDir, '..', 'web-ui');
  if (existsSync(bundledPath)) {
    return bundledPath;
  }

  return null;
}

// WebSocket pub/sub and heartbeat managers
let pubsubManager: PubSubManager;
let heartbeatManager: HeartbeatManager;
let wsHandler: WebSocketHandler;
let projectManager: import('./project-context').ProjectContextManager | undefined;
let shadowSyncScheduler: ShadowSyncScheduler | undefined;
let sessionSyncScheduler: SessionSyncScheduler | undefined;

/**
 * Middleware to enforce localhost-only connections.
 * AC-3: Reject non-localhost connections with 403 Forbidden
 */
function localhostOnly() {
  return (context: { request: Request }) => {
    const host = context.request.headers.get('host');
    if (!host) {
      return new Response(JSON.stringify({
        error: 'Forbidden',
        message: 'This server only accepts connections from localhost'
      }), {
        status: 403,
        headers: { 'Content-Type': 'application/json' }
      });
    }

    // Extract hostname, handling IPv6 brackets
    let hostname: string;
    if (host.startsWith('[')) {
      // IPv6 with brackets: [::1]:3456 -> ::1
      const closeBracket = host.indexOf(']');
      hostname = closeBracket > 0 ? host.substring(1, closeBracket) : host;
    } else {
      // IPv4 or hostname: localhost:3456 -> localhost
      hostname = host.split(':')[0];
    }

    // Allow localhost, 127.0.0.1, and ::1
    const isLocalhost =
      hostname === 'localhost' ||
      hostname === '127.0.0.1' ||
      hostname === '::1';

    if (!isLocalhost) {
      return new Response(JSON.stringify({
        error: 'Forbidden',
        message: 'This server only accepts connections from localhost'
      }), {
        status: 403,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  };
}

/**
 * Creates and configures the Elysia server instance.
 *
 * AC Coverage:
 * - ac-1: Server starts on configurable port (default 3456)
 * - ac-2: Binds to localhost only (127.0.0.1 and ::1)
 * - ac-3: Rejects non-localhost connections with 403
 * - ac-15: Uses plugin pattern for middleware
 */
export async function createServer(options: ServerOptions) {
  const { port, isDaemon, kspecDir = join(process.cwd(), '.kspec'), webUiDir } = options;

  // Determine startup project path (project root, not .kspec/)
  // AC: @multi-directory-daemon ac-2 - daemon uses startup directory as default project
  const startupProjectPath = kspecDir.endsWith('.kspec')
    ? kspecDir.slice(0, -('.kspec'.length + 1)) // Remove '/.kspec'
    : kspecDir;

  // Import ProjectContextManager (needed for WebSocket binding)
  const { ProjectContextManager } = await import('./project-context');

  // AC: @daemon-server ac-17 - Resolve web UI path for static file serving
  const resolvedWebUiPath = resolveWebUiPath(webUiDir);
  if (resolvedWebUiPath) {
    console.log(`[daemon] Web UI assets found at: ${resolvedWebUiPath}`);
  } else {
    console.log('[daemon] Web UI assets not found - UI will not be served');
    console.log('[daemon] Build the web UI with: cd packages/web-ui && npm run build');
  }

  // Initialize PID file manager (uses global ~/.config/kspec/)
  const pidManager = new PidFileManager();

  // AC: @multi-directory-daemon ac-9 - Write PID and port files in daemon mode
  if (isDaemon) {
    pidManager.writePid();
    pidManager.writePort(port);
    console.log(`[daemon] PID file written: ${process.pid}`);
    console.log(`[daemon] Port file written: ${port}`);
  }

  // Initialize WebSocket managers
  pubsubManager = new PubSubManager();
  heartbeatManager = new HeartbeatManager();
  wsHandler = new WebSocketHandler(pubsubManager);

  // WeakMap to store project path during WebSocket upgrade (keyed by Request object)
  // Using WeakMap avoids needing to pass a requestId through beforeHandle return value,
  // which breaks WebSocket upgrade in Elysia 1.4 when derive middleware is present.
  const wsProjectPaths = new WeakMap<Request, string>();

  const app = new Elysia()
    // AC-15: Plugin pattern for middleware
    // AC: @api-contract ac-1 - Allow CORS from dev server on localhost:5173
    .use(cors({
      origin: ['http://localhost:5173', 'http://127.0.0.1:5173'], // Dev server origins
      credentials: true,
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS']
    }))

    // AC-3: Enforce localhost-only connections
    .onRequest(localhostOnly());

  // AC: @multi-directory-daemon ac-1, ac-2, ac-3 - Project context middleware
  const { manager: projectContextManager, middleware: projectMiddleware } = projectContextMiddleware({
    startupProject: startupProjectPath,
    pubsub: pubsubManager
  });

  // Store manager globally for shutdown
  projectManager = projectContextManager;

  app.use(projectMiddleware)

    // AC-11: Health check endpoint
    .get('/api/health', () => ({
      status: 'ok',
      uptime: process.uptime(),
      connections: pubsubManager.getConnectionCount(),
      version: '0.1.0'
    }))

    // AC: @api-contract ac-2 through ac-7 - Task API endpoints
    // AC: @multi-directory-daemon ac-24 - Routes use projectContext from middleware
    .use(createTasksRoutes({ pubsub: pubsubManager }))

    // AC: @api-contract ac-8 through ac-11 - Spec Item API endpoints
    .use(createItemsRoutes())

    // AC: @api-contract ac-12 through ac-14 - Inbox API endpoints
    .use(createInboxRoutes({ pubsub: pubsubManager }))

    // AC: @api-contract ac-15 through ac-18 - Meta API endpoints
    .use(createMetaRoutes())

    // AC: @triage-daemon-api ac-1 through ac-9 - Triage API endpoints
    .use(createTriageRoutes({ pubsub: pubsubManager }))

    // AC: @api-contract ac-19 through ac-21 - Validation and search endpoints
    .use(createValidationRoutes())

    // AC: @multi-directory-daemon ac-28, ac-29, ac-30 - Projects management endpoints
    .use(createProjectsRoutes({ projectManager: projectContextManager }))

    // AC: @ui-session-stream ac-1, ac-4 - Session data endpoints
    .use(createSessionRoutes())

    // AC: @ui-plans-view ac-1 - Plans data endpoints
    .use(createPlansRoutes())

    // AC: @agent-dispatch-engine ac-4 - Agent dispatch API endpoints
    // AC: @daemon-agent-dispatch ac-3, ac-4 - Pass pubsub for WebSocket broadcast on invocation events
    .use(createAgentDispatchRoutes({ pubsub: pubsubManager }))

    // AC-4: WebSocket endpoint for real-time updates
    .ws<ConnectionData>('/ws', {
      beforeHandle({ request, store }) {
        // AC: @multi-directory-daemon ac-21, ac-22, ac-23, ac-34 - Extract and validate project binding
        // AC: @multi-directory-daemon ac-34 - Browser WebSocket API doesn't support custom headers,
        // so we also accept project path as query parameter
        const url = new URL(request.url, `http://${request.headers.get('host')}`);
        const projectPath = request.headers.get('X-Kspec-Dir')
                        || url.searchParams.get('project')
                        || undefined;

        // IMPORTANT: Do NOT return a value from ws beforeHandle.
        // In Elysia 1.4 with derive middleware, returning a value short-circuits
        // the WebSocket upgrade and sends the value as an HTTP 200 response.
        // Use a WeakMap keyed by Request object to pass data to open().
        try {
          const manager = (store as Record<string, unknown>).projectManager as import('./project-context').ProjectContextManager | undefined;
          if (!manager) {
            // Fallback: project manager not initialized yet
            wsProjectPaths.set(request, startupProjectPath);
            return;
          }

          let projectContext;
          if (projectPath) {
            // Explicit project specified
            try {
              projectContext = manager.getProject(projectPath);
            } catch {
              // AC: @multi-directory-daemon ac-4 - auto-register
              projectContext = manager.registerProject(projectPath);
            }
          } else {
            // AC: @multi-directory-daemon ac-22, ac-23 - Use default or reject
            try {
              projectContext = manager.getProject();
            } catch (err: unknown) {
              // AC: @multi-directory-daemon ac-23 - Reject when no default
              if (err instanceof Error && err.message.includes('No default project configured')) {
                throw new Error('No project specified');
              }
              throw err;
            }
          }

          // Store resolved path for open() handler via WeakMap
          wsProjectPaths.set(request, projectContext.path);
        } catch (err: unknown) {
          console.error(`[daemon] WebSocket connection rejected: ${err instanceof Error ? err.message : String(err)}`);
          throw err;
        }
      },
      open(ws) {
        // AC: @api-contract ac-25, @trait-websocket-protocol ac-1
        const sessionId = ulid();
        const openContext = ws.data as { id?: unknown; request?: unknown } | undefined;
        const contextId = typeof openContext?.id === 'string' ? openContext.id : undefined;

        // AC: @multi-directory-daemon ac-21 - Get bound project path
        // Retrieve project path from WeakMap via the request object on ws.data
        const request = openContext?.request as Request | undefined;
        const projectPath = request ? wsProjectPaths.get(request) || startupProjectPath : startupProjectPath;

        ws.data = {
          sessionId,
          topics: new Set<string>(),
          seq: 0,
          lastPing: undefined,
          lastPong: Date.now(),
          projectPath // AC: @multi-directory-daemon ac-21 - immutable binding
        };

        pubsubManager.addConnection(sessionId, ws, contextId);
        console.log(`[daemon] WebSocket client connected: ${sessionId} bound to ${projectPath} (${pubsubManager.getConnectionCount()} total)`);

        // Send connected event with session_id
        const connectedEvent: ConnectedEvent = {
          event: 'connected',
          data: {
            session_id: sessionId
          }
        };
        ws.send(JSON.stringify(connectedEvent));
      },
      message(ws, message) {
        // AC: @api-contract ac-26, ac-27
        wsHandler.handleMessage(ws, message);
      },
      pong(ws) {
        // AC: @trait-websocket-protocol ac-5
        heartbeatManager.recordPong(ws);
      },
      close(ws, code, reason) {
        handleWebSocketClose(pubsubManager, ws, code, reason);
      }
    });

  // AC: @daemon-server ac-17 - Serve web UI static assets
  // Added after API routes so API routes take precedence
  if (resolvedWebUiPath) {
    const indexHtmlPath = join(resolvedWebUiPath, 'index.html');

    // Serve static files from web UI build directory
    app.use(await staticPlugin({
      assets: resolvedWebUiPath,
      prefix: '/',
      noCache: process.env.NODE_ENV === 'development', // Disable cache in dev
    }));

    // SPA fallback routes for client-side routing
    // These catch paths like /tasks, /items, /inbox that don't have static files
    const spaRoutes = [
      '/',
      '/tasks', '/tasks/*',
      '/items', '/items/*',
      '/inbox',
      '/observations',
      '/triage',
      '/validate',
      '/sessions', '/sessions/*',
      '/agents',
      '/specs',
      '/workflows',
      '/plans',
      '/settings',
    ];
    for (const route of spaRoutes) {
      app.get(route, () => Bun.file(indexHtmlPath));
    }

    console.log('[daemon] Web UI static file serving enabled');
  }

  // AC-1, AC-2: Start server on localhost only
  // Using 'localhost' hostname allows Bun/OS to bind to both 127.0.0.1 and ::1
  app.listen({
    port,
    hostname: 'localhost', // Resolves to both IPv4 and IPv6 loopback
  });

  console.log(`[daemon] Server listening on http://localhost:${port} (IPv4: 127.0.0.1, IPv6: ::1)`);
  console.log(`[daemon] WebSocket available at ws://localhost:${port}/ws`);

  // AC: @agent-dispatch-engine ac-5 - Wire file change callback to dispatch engine
  projectContextManager.setFileChangeCallback((projectPath, file) => {
    // Only forward changes to project.tasks.yaml
    if (!file.endsWith('project.tasks.yaml')) return;
    const engine = getDispatchEngine(projectPath);
    if (engine) {
      engine.handleFileChange(projectPath).catch((err) => {
        console.error('[dispatch] Error handling file change:', err);
      });
    }
  });

  // AC: @multi-directory-daemon ac-17 - Start file watcher for startup project
  if (startupProjectPath) {
    try {
      await projectContextManager.startWatcher(startupProjectPath);
      console.log(`[daemon] File watcher started for startup project: ${startupProjectPath}`);
    } catch (error) {
      console.error('[daemon] Failed to start file watcher for startup project:', error);
    }
  }

  // AC: @config-shadow ac-12 - Start periodic shadow sync if remote tracking configured
  if (startupProjectPath) {
    try {
      const { loadProjectConfig } = await import('../parser/config.js');
      const { config } = await loadProjectConfig(startupProjectPath);
      const syncInterval = config.shadow.sync_interval;
      const worktreeDir = join(startupProjectPath, config.shadow.directory);

      if (syncInterval > 0) {
        shadowSyncScheduler = new ShadowSyncScheduler({
          worktreeDir,
          intervalSeconds: syncInterval,
          shadowOptions: {
            branchName: config.shadow.branch,
            directory: config.shadow.directory,
            remote: config.shadow.remote?.value,
            remoteType: config.shadow.remote?.type,
          },
          pubsub: pubsubManager,
        });
        shadowSyncScheduler.start();
      }
    } catch (error) {
      console.error('[daemon] Failed to initialize shadow sync scheduler:', error);
    }
  }

  // AC: @session-branch-worktree ac-sync - Start periodic session branch sync if configured
  // Session sync runs independently from kspec-meta sync — failures in one do not affect the other
  if (startupProjectPath) {
    try {
      const { readFileSync } = await import('fs');
      const { parse: parseYaml } = await import('yaml');
      const manifestPath = join(startupProjectPath, '.kspec', 'kynetic.yaml');
      const manifestRaw = readFileSync(manifestPath, 'utf-8');
      const manifest = parseYaml(manifestRaw) as { sessions?: { storage?: string; branch?: string } } | null;

      if (manifest?.sessions?.storage === 'branch') {
        const { loadProjectConfig } = await import('../parser/config.js');
        const { config } = await loadProjectConfig(startupProjectPath);
        const syncInterval = config.shadow.sync_interval;

        if (syncInterval > 0) {
          const sessionBranchName = manifest.sessions.branch || 'kspec-sessions';
          const sessionWorktreeDir = join(startupProjectPath, '.kspec-sessions');

          sessionSyncScheduler = new SessionSyncScheduler({
            worktreeDir: sessionWorktreeDir,
            intervalSeconds: syncInterval,
            branchName: sessionBranchName,
            pubsub: pubsubManager,
          });
          sessionSyncScheduler.start();
        }
      }
    } catch (error) {
      // Session sync init failure does not block daemon startup
      console.error('[daemon] Failed to initialize session sync scheduler:', error);
    }
  }

  // AC: @daemon-server ac-13, ac-14 - Start heartbeat monitoring
  heartbeatManager.start(pubsubManager.getAllConnections());

  // AC-12: Graceful shutdown on SIGTERM/SIGINT
  const shutdown = async (signal: string) => {
    console.log(`[daemon] Received ${signal}, shutting down gracefully...`);

    try {
      // Stop heartbeat monitoring
      heartbeatManager.stop();

      // AC: @config-shadow ac-12 - Stop shadow sync scheduler
      shadowSyncScheduler?.stop();

      // AC: @session-branch-worktree ac-sync - Stop session sync scheduler
      sessionSyncScheduler?.stop();

      // AC: @agent-dispatch-engine ac-11 - Stop all dispatch engines before shutting down
      await stopAllEngines();

      // AC: @multi-directory-daemon ac-11b - Stop all file watchers
      await projectContextManager.stopAllWatchers();
      console.log('[daemon] All file watchers stopped');

      // Close all WebSocket connections with code 1000 (clean close)
      // AC: @trait-websocket-protocol ac-7
      for (const [sessionId, ws] of pubsubManager.getAllConnections()) {
        ws.close(1000, 'Server shutting down');
      }

      // Stop the server
      await app.server?.stop();

      // AC: @daemon-server ac-10 - Remove PID file on shutdown
      if (isDaemon) {
        pidManager.remove();
        console.log('[daemon] PID file removed');
      }

      console.log('[daemon] Server stopped successfully');
      process.exit(0);
    } catch (error) {
      console.error('[daemon] Error during shutdown:', error);
      process.exit(1);
    }
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));

  return app;
}

