    const scheduler = new SessionSyncScheduler({
      worktreeDir: "/nonexistent",
      intervalSeconds: 0,
      branchName: SESSION_BRANCH_NAME,
    });

    // start() should be a no-op
    scheduler.start();
    scheduler.stop();
  });

